--- /dev/null
+++ b/tests/rag-repairs/conversation-context.test.ts
@@ -0,0 +1,49 @@
+import { afterEach, describe, expect, it, vi } from "vitest";
+
+import { buildHelpRetrievalQuery } from "@/lib/ai/help-chat";
+import { getHelpChatConfig } from "@/lib/help-chat-config";
+
+afterEach(() => vi.unstubAllEnvs());
+
+describe("retrieval conversation context", () => {
+  it("defaults to the recent user topic without assistant text or older topics", () => {
+    vi.stubEnv("RELAYDESK_HELP_INCLUDE_CONTEXT", undefined);
+
+    const query = buildHelpRetrievalQuery(
+      [
+        { role: "user", content: "An older unrelated topic" },
+        { role: "user", content: "  Configure notification preferences  " },
+        { role: "assistant", content: "Unverified assistant suggestion" },
+        { role: "user", content: "  Where is that setting?  " },
+      ],
+      getHelpChatConfig(),
+    );
+
+    expect(query).toBe(
+      "Configure notification preferences\nFollow-up: Where is that setting?",
+    );
+  });
+
+  it("preserves a standalone retrieval query", () => {
+    vi.stubEnv("RELAYDESK_HELP_INCLUDE_CONTEXT", undefined);
+    expect(
+      buildHelpRetrievalQuery(
+        [{ role: "user", content: "Configure notification preferences" }],
+        getHelpChatConfig(),
+      ),
+    ).toBe("Configure notification preferences");
+  });
+
+  it("preserves the explicit context opt-out", () => {
+    vi.stubEnv("RELAYDESK_HELP_INCLUDE_CONTEXT", "false");
+    expect(
+      buildHelpRetrievalQuery(
+        [
+          { role: "user", content: "Configure notification preferences" },
+          { role: "user", content: "Where is that setting?" },
+        ],
+        getHelpChatConfig(),
+      ),
+    ).toBe("Where is that setting?");
+  });
+});
